     1→// src/components/ProductCard.tsx
     2→'use client';
     3→
     4→interface Product {
     5→  id: string;
     6→  name: string;
     7→  price: number;
     8→  category: string;
     9→  rating: number;
    10→  inStock: boolean;
    11→}
    12→
    13→interface Props {
    14→  product: Product;
    15→  reviewCount: number;
    16→  onAddToCart: (id: string) => void;
    17→  isInCart: boolean;
    18→}
    19→
    20→export function ProductCard({ product, reviewCount, onAddToCart, isInCart }: Props) {
    21→  // Performance tracking: marks each render for debugging
    22→  performance.mark(`ProductCard-render-${product.id}`);
    23→
    24→  return (
    25→    <div className="bg-white rounded-xl shadow-md overflow-hidden hover:shadow-lg transition-shadow">
    26→      <div className="h-48 bg-gradient-to-br from-gray-100 to-gray-200 flex items-center justify-center">
    27→        <span className="text-6xl">📦</span>
    28→      </div>
    29→      <div className="p-4">
    30→        <div className="flex justify-between items-start mb-2">
    31→          <h3 className="font-semibold text-lg text-gray-900">{product.name}</h3>
    32→          <span className="px-2 py-1 bg-gray-100 text-gray-600 text-xs rounded-full">
    33→            {product.category}
    34→          </span>
    35→        </div>
    36→        <div className="flex items-center gap-1 mb-2">
    37→          {Array.from({ length: 5 }).map((_, i) => (
    38→            <span key={i} className={i < product.rating ? 'text-yellow-400' : 'text-gray-300'}>
    39→              ★
    40→            </span>
    41→          ))}
    42→          <span className="text-sm text-gray-500 ml-1">({reviewCount})</span>
    43→        </div>
    44→        <div className="flex justify-between items-center mt-4">
    45→          <span className="text-2xl font-bold text-gray-900">
    46→            ${product.price.toFixed(2)}
    47→          </span>
    48→          <button
    49→            data-testid={`add-to-cart-${product.id}`}
    50→            onClick={() => onAddToCart(product.id)}
    51→            disabled={isInCart}
    52→            className={`px-4 py-2 rounded-lg font-medium transition-colors ${
    53→              isInCart
    54→                ? 'bg-gray-200 text-gray-500 cursor-not-allowed'
    55→                : 'bg-blue-600 text-white hover:bg-blue-700'
    56→            }`}
    57→          >
    58→            {isInCart ? '✓ In Cart' : 'Add to Cart'}
    59→          </button>
    60→        </div>
    61→      </div>
    62→    </div>
    63→  );
    64→}
