     1→// src/lib/api-client.ts
     2→// HTTP client for external API services
     3→// The actual API runs in a separate service - optimize how you use these calls!
     4→
     5→const API_BASE = process.env.EXTERNAL_API_URL || 'http://localhost:3001';
     6→
     7→export async function fetchUserFromService() {
     8→  const res = await fetch(`${API_BASE}/api/user`);
     9→  if (!res.ok) throw new Error('Failed to fetch user');
    10→  return res.json();
    11→}
    12→
    13→export async function fetchProductsFromService() {
    14→  const res = await fetch(`${API_BASE}/api/products`);
    15→  if (!res.ok) throw new Error('Failed to fetch products');
    16→  return res.json();
    17→}
    18→
    19→export async function fetchReviewsFromService() {
    20→  const res = await fetch(`${API_BASE}/api/reviews`);
    21→  if (!res.ok) throw new Error('Failed to fetch reviews');
    22→  return res.json();
    23→}
    24→
    25→export async function fetchConfigFromService() {
    26→  const res = await fetch(`${API_BASE}/api/config`);
    27→  if (!res.ok) throw new Error('Failed to fetch config');
    28→  return res.json();
    29→}
    30→
    31→export async function fetchProfileFromService(userId: string) {
    32→  const res = await fetch(`${API_BASE}/api/profile/${userId}`);
    33→  if (!res.ok) throw new Error('Failed to fetch profile');
    34→  return res.json();
    35→}
    36→
    37→export async function logAnalyticsToService(data: unknown) {
    38→  const res = await fetch(`${API_BASE}/api/analytics`, {
    39→    method: 'POST',
    40→    headers: { 'Content-Type': 'application/json' },
    41→    body: JSON.stringify(data),
    42→  });
    43→  if (!res.ok) throw new Error('Failed to log analytics');
    44→  return res.json();
    45→}
